vulnerable_code:
app.get('/api/orders/search', async (req, res) => {
  const orders = await Order.findAll();
  const match = orders.find(o => o.id == req.query.id);
  res.json(match);
});

corrected_code:
app.get('/api/orders/search', async (req, res) => {
  const orders = await Order.findAll({ where: { userId: req.user.id } });
  const match = orders.find(o => o.id == req.query.id);
  res.json(match);
});
